#!/usr/bin/env bash
set -euo pipefail

# MediaForge Wan VACE Web Terminal bundle.
# Paste or upload this script inside the RunPod Web Terminal, then run:
#   bash mediaforge_wan_vace_web_terminal_bundle.sh
#
# Optional modes:
#   MEDIAFORGE_INSTALL_MODE=full  bash mediaforge_wan_vace_web_terminal_bundle.sh
#   MEDIAFORGE_INSTALL_MODE=light bash mediaforge_wan_vace_web_terminal_bundle.sh
#   MEDIAFORGE_INSTALL_MODE=none  bash mediaforge_wan_vace_web_terminal_bundle.sh

decode_b64_file() {
  local target="$1"
  mkdir -p "$(dirname "$target")"
  if command -v base64 >/dev/null 2>&1; then
    base64 -d > "$target"
  else
    python3 -c 'import base64, sys; sys.stdout.buffer.write(base64.b64decode(sys.stdin.buffer.read()))' > "$target"
  fi
}

