  fi
fi

case "$INSTALL_MODE" in
  full)
    echo 'Running full ComfyUI + Qwen + Wan VACE install...'
    /workspace/install_comfy_wan_vace.sh
    ;;
  light)
    echo 'Running light Wan VACE dependency/model install...'
    /workspace/install_wan_vace_light.sh
    ;;
  none)
    echo 'Skipping install; using existing ComfyUI and models.'
    ;;
  *)
    echo "Unknown MEDIAFORGE_INSTALL_MODE: $INSTALL_MODE" >&2
    exit 1
    ;;
esac

/workspace/start_wan_vace_services.sh
echo
echo "External checks should pass when RunPod exposes port ${WAN_WORKER_PORT:-8888}:"
echo '  /health'
echo '  /diagnostics'
echo '  /preflight'
echo '  /qwen/preflight'
